  readonly completedBy: ChorePerson | null;
  readonly contributor: ChorePerson | null;
  readonly note: string | null;
  readonly skippedAt: string | null;
  readonly skippedBy: ChorePerson | null;
  readonly skipReason: string | null;
  readonly approvedAt: string | null;
  readonly approvedBy: ChorePerson | null;
