/** Why a chore request failed, in words the interface can explain. */
export type ChoreFailure =
  | "signedOut"
  | "invalid"
  | "notFound"
  | "notPermitted"
  | "conflict"
  | "duplicateName"
  | "limitReached"
  | "stepsIncomplete"
  | "alreadyCompleted"
  | "alreadySkipped"
  | "alreadySubmitted"
  | "pendingApproval"
  | "notPending"
  | "contributorUnavailable"
  | "notCompleted"
  | "occurrenceClosed"
  | "needsConfirmation"
  | "scopeUnavailable"
  | "notRecurring"
  | "scheduleEnded"
  | "network"
  | "failed";

export class ChoreRequestError extends Error {
  constructor(
    readonly failure: ChoreFailure,
    /** For a conflict, the current revision when known; for stepsIncomplete, the open count. */
    readonly detail: number | null = null,
    readonly fields: readonly string[] = [],
  ) {
    super(`Chore request failed: ${failure}`);
    this.name = "ChoreRequestError";
  }
}

const failures: { readonly [C in ChoreErrorCode]?: ChoreFailure } = {
  unauthenticated: "signedOut",
  invalid: "invalid",
  "not-found": "notFound",
  "not-permitted": "notPermitted",
  conflict: "conflict",
  "duplicate-name": "duplicateName",
  "limit-reached": "limitReached",
  "id-taken": "failed",
  "steps-incomplete": "stepsIncomplete",
  "already-completed": "alreadyCompleted",
  "already-skipped": "alreadySkipped",
  "already-submitted": "alreadySubmitted",
  "pending-approval": "pendingApproval",
  "not-pending": "notPending",
  "contributor-unavailable": "contributorUnavailable",
  "not-completed": "notCompleted",
  "occurrence-closed": "occurrenceClosed",
  "needs-confirmation": "needsConfirmation",
  "scope-unavailable": "scopeUnavailable",
  "not-recurring": "notRecurring",
  "schedule-ended": "scheduleEnded",
};

/** Sends one request; resolves with the JSON answer or rejects with a ChoreRequestError. */
export async function sendChoreRequest<T>(method: string, url: string, body?: unknown): Promise<T> {
  let response: Response;
  try {
    response = await fetch(url, {
      method,
      headers: body === undefined ? {} : { "content-type": "application/json" },
      ...(body === undefined ? {} : { body: JSON.stringify(body) }),
      cache: "no-store",
    });
  } catch {
    throw new ChoreRequestError("network");
  }
  const payload: unknown = await response.json().catch(() => null);
  if (!response.ok) {
    const record = (payload && typeof payload === "object" ? payload : {}) as Partial<
      Record<string, unknown>
    >;
    const code = typeof record.error === "string" ? (record.error as ChoreErrorCode) : "failed";
    const detail =
      typeof record.revision === "number"
        ? record.revision
        : typeof record.count === "number"
          ? record.count
          : null;
    const fields = Array.isArray(record.fields)
      ? record.fields.filter((field): field is string => typeof field === "string")
      : [];
    throw new ChoreRequestError(failures[code] ?? "failed", detail, fields);
  }
  return payload as T;
}
